def export_titles(rows):
    return "\n".join(row["title"] for row in rows)
assert export_titles([{"title": "Patterns"}]) == "Patterns"
assert export_titles([]) == ""

def minutes(value):
    if type(value) is not int or value < 0:
        raise ValueError("nonnegative integer required")
    return value
assert minutes(0) == 0
try:
    minutes(True)
except ValueError:
    pass
else:
    raise AssertionError("bool was accepted")

from typing import Protocol
class TitleSource(Protocol):
    def titles(self) -> list[str]: ...
class MemorySource:
    def titles(self):
        return ["Patterns"]
def summary(source: TitleSource):
    return ", ".join(source.titles())
assert summary(MemorySource()) == "Patterns"

def arrange(rows, key):
    return sorted(rows, key=key)
rows = [{"title": "SQL", "minutes": 30}, {"title": "Python", "minutes": 10}]
assert [r["title"] for r in arrange(rows, lambda r: r["minutes"])] == ["Python", "SQL"]
assert rows[0]["title"] == "SQL"

