import json
def formatter_for(name):
    if name == "json":
        return lambda titles: json.dumps(titles)
    if name == "lines":
        return lambda titles: "\n".join(titles)
    raise ValueError("unknown format")
assert formatter_for("lines")(["A", "B"]) == "A\nB"

from dataclasses import dataclass
@dataclass(frozen=True)
class Report:
    title: str
    fields: tuple[str, ...]
class Builder:
    def __init__(self):
        self.fields = []
    def field(self, name):
        self.fields.append(name)
        return self
    def build(self, title):
        if not title.strip() or not self.fields or any(not f.strip() for f in self.fields):
            raise ValueError("title and fields required")
        return Report(title.strip(), tuple(self.fields))
b = Builder().field("title")
r = b.build(" Progress ")
b.field("minutes")
assert r.fields == ("title",)

class Legacy:
    def seconds_spent(self):
        return 125
class MinutesAdapter:
    def __init__(self, legacy):
        self.legacy = legacy
    def minutes(self):
        seconds = self.legacy.seconds_spent()
        if type(seconds) is not int or seconds < 0:
            raise ValueError("invalid seconds")
        return seconds // 60
assert MinutesAdapter(Legacy()).minutes() == 2

def publish(titles, format_titles, deliver):
    if any(not isinstance(t, str) or not t.strip() for t in titles):
        raise ValueError("invalid title")
    document = format_titles(titles)
    deliver(document)
    return len(titles)
out = []
assert publish(["Patterns"], lambda xs: "|".join(xs), out.append) == 1
assert out == ["Patterns"]

from dataclasses import dataclass
@dataclass(frozen=True)
class Lesson:
    minutes: int
    def duration(self):
        return self.minutes
@dataclass(frozen=True)
class Module:
    children: tuple
    def duration(self):
        return sum(child.duration() for child in self.children)
plan = Module((Lesson(10), Module((Lesson(20),))))
assert plan.duration() == 30
assert Module(()).duration() == 0

class LazyDocument:
    def __init__(self, load):
        self.load, self.loaded, self.value = load, False, None
    def get(self):
        if not self.loaded:
            value = self.load()
            self.value, self.loaded = value, True
        return self.value
calls = []
p = LazyDocument(lambda: calls.append("load"))
assert p.get() is None and p.get() is None
assert calls == ["load"]

class Events:
    def __init__(self):
        self.handlers = []
    def subscribe(self, handler):
        self.handlers.append(handler)
    def unsubscribe(self, handler):
        self.handlers.remove(handler)
    def publish(self, event):
        for handler in tuple(self.handlers):
            handler(event)
events = Events()
seen = []
events.subscribe(seen.append)
events.publish("lesson-completed")
assert seen == ["lesson-completed"]

class Rename:
    def __init__(self, book, title):
        self.book, self.title, self.before = book, title, None
    def execute(self):
        if self.before is not None:
            raise ValueError("already executed")
        self.before = self.book["title"]
        self.book["title"] = self.title
    def undo(self):
        if self.before is None or self.book["title"] != self.title:
            raise ValueError("cannot safely undo")
        self.book["title"] = self.before
        self.before = None
book = {"title": "A"}
cmd = Rename(book, "B")
cmd.execute(); cmd.undo()
assert book["title"] == "A"

TRANSITIONS = {("draft", "start"): "active", ("active", "pause"): "draft", ("active", "finish"): "done"}
def transition(state, action):
    try:
        return TRANSITIONS[state, action]
    except KeyError:
        raise ValueError("illegal transition") from None
assert transition("draft", "start") == "active"
assert transition("active", "finish") == "done"

class ReportJob:
    def run(self):
        rows = self.load()
        if any(not isinstance(x, str) for x in rows):
            raise ValueError("strings required")
        return self.render(rows)
    def load(self):
        raise NotImplementedError
    def render(self, rows):
        return "\n".join(rows)
class MemoryJob(ReportJob):
    def load(self):
        return ["Patterns"]
assert MemoryJob().run() == "Patterns"

