class Progress:
    def __init__(self, save, clock):
        self.save, self.clock = save, clock
    def complete(self, title):
        self.save({"title": title, "at": self.clock()})
records = []
service = Progress(records.append, lambda: "2026-01-01T00:00:00Z")
service.complete("Patterns")
assert records[0]["at"] == "2026-01-01T00:00:00Z"

from dataclasses import dataclass
@dataclass(frozen=True)
class Lesson:
    id: str
    title: str
class Repository:
    def __init__(self):
        self.rows = {}
    def add(self, lesson):
        if lesson.id in self.rows:
            raise ValueError("duplicate ID")
        self.rows[lesson.id] = lesson
    def get(self, id):
        return self.rows.get(id)
r = Repository()
r.add(Lesson("1", "Patterns"))
assert r.get("1").title == "Patterns"
assert r.get("missing") is None

from contextlib import contextmanager
from copy import deepcopy
@contextmanager
def unit_of_work(store):
    working = deepcopy(store)
    yield working
    store.clear()
    store.update(working)
store = {"completed": 0}
try:
    with unit_of_work(store) as work:
        work["completed"] = 1
        raise ValueError("abort")
except ValueError:
    pass
assert store == {"completed": 0}
with unit_of_work(store) as work:
    work["completed"] = 1
assert store == {"completed": 1}

def old(titles, kind):
    if kind == "lines":
        return "\n".join(titles)
    raise ValueError("unknown format")
def lines(titles):
    return "\n".join(titles)
def new(titles, formatter):
    return formatter(titles)
for titles in ([], ["A"], ["A", "B"]):
    assert old(titles, "lines") == new(titles, lines)

# A runnable minimal alternative: explicit functions and one selection point.
def preview(titles, format_name):
    formatters = {"lines": lambda xs: "\n".join(xs), "count": lambda xs: str(len(xs))}
    if format_name not in formatters:
        raise ValueError("unsupported preview")
    return formatters[format_name](titles)
assert preview(["A", "B"], "count") == "2"
